source:
This operation on sets---combining them---is very useful and common,
and so we give it a formal name and a symbol. 
\end{explain}

target:
\begin{defn}[اتحاد]
د دوو سټونو $A$ او $B$ \emph{اتحاد}، چې $A \cup B$ ليکل کېږي، د ټولو هغو څيزونو سټ دے چې د $A$، $B$، يا د دواړو !!{element}s وي۔
\[
A \cup B = \Setabs{x}{x \in A \lor x \in B}
\]
\end{defn}

source:
The union of a set with the empty set is identical to the set: $\{a,
b, c \} \cup \emptyset = \{a, b, c \}$.
\end{ex}

\begin{prob}
Prove that if $A \subseteq B$, then $A \cup B = B$.
\end{prob}

target:
\begin{prob}
ثابت کړئ چې که $A \subseteq B$ وي، نو $A \cup B = B$۔
\end{prob}

source:
\begin{explain}
We can also consider a ``dual'' operation to union. This is the
operation that forms the set of all !!{element}s that are !!{element}s
of~$A$ and are also !!{element}s of~$B$. This operation is called 
\emph{intersection}, and can be depicted as in \olref{fig:intersection}.
\begin{figure}
  \olasset{assets/diagrams/intersection.tikz}
  \caption{The intersection $A \cap B$ of two sets is the set of
    !!{element}s they have in common.}
  \ollabel{fig:intersection}
\end{figure}
\end{explain}

target:
\begin{explain}
د اتحاد يو ``دوه ګونے'' عمل هم په پام کښې نيولے شو۔ دا هغه عمل دے چې د هغو ټولو \psOblique{!!{element}s} سټ جوړوي چې د~$A$ !!{element}s وي او د~$B$ هم !!{element}s وي۔ دې عمل ته \emph{تقاطع} وئيل کېږي، او لکه په \olref{fig:intersection} کښې ښودل کېدے شي۔
\begin{figure}
  \olasset{assets/diagrams/intersection.tikz}
  \caption{د دوو سټونو تقاطع $A \cap B$ د هغو د ګډو \psOblique{!!{element}s} سټ دے۔}
  \ollabel{fig:intersection}
\end{figure}
\end{explain}

source:
\begin{ex}
If two sets have no !!{element}s in common, their intersection is empty:
$\{ a, b, c\} \cap \{ 0, 1\} = \emptyset$.

The intersection of any set with the empty set is empty: $\{a, b, c \}
\cap \emptyset = \emptyset$.
\end{ex}

\begin{prob}
Prove rigorously that if $A \subseteq B$, then $A \cap B = A$.
\end{prob}

target:
\begin{prob}
په دقيقه توګه ثابت کړئ چې که $A \subseteq B$ وي، نو $A \cap B = A$۔
\end{prob}

\begin{explain}
له دوو څخه د زياتو سټونو اتحاد يا تقاطع هم جوړولے شو۔ په عمومي توګه د دې د بيانولو يوه ښکلې طريقه دا ده: فرض کړئ چې ټول هغه سټونه چې اتحاد (يا تقاطع) ئې جوړول غواړئ، په يو سټ کښې راټول کړئ۔ بيا د ټولو اصلي سټونو اتحاد د هغو ټولو څيزونو د سټ په توګه تعريفولے شو چې لږ تر لږه د دې سټ د يو \psOblique{!!{element}} غړي وي، او تقاطع د هغو ټولو څيزونو د سټ په توګه چې د دې سټ د هر \psOblique{!!{element}} غړي وي۔
\end{explain}

source:
\begin{defn}
If $A$ is a set of sets, then $\bigcup A$ is the set of !!{element}s of
!!{element}s of~$A$:
\begin{align*}
\bigcup A & = \Setabs{x}{x \text{ belongs to !!a{element} of } A},
\text{ i.e.,}\\
& = \Setabs{x}{\text{there is a } B \in A
  \text{ so that } x \in B}
\end{align*}
\end{defn}

target:
\begin{defn}
که $A$ د سټونو يو سټ وي، نو $\bigcup A$ د~$A$ د \psOblique{!!{element}s} د \psOblique{!!{element}s} سټ دے:
\begin{align*}
\bigcup A & = \Setabs{x}{x \text{ د دې سټ د يو \psOblique{!!a{element}} غړے دے: } A},
\text{ يعنې،}\\
& = \Setabs{x}{\text{داسې يو } B \in A
  \text{ شته چې } x \in B}
\end{align*}
\end{defn}

source:
\begin{defn}
If $A$ is a set of sets, then $\bigcap A$ is the set of objects which
all elements of~$A$ have in common:
\begin{align*}
\bigcap A & = \Setabs{x}{x \text{ belongs to every !!{element} of } A},
\text{ i.e.,}\\
 & = \Setabs{x}{\text{for all } B \in A, x \in B}
\end{align*}
\end{defn}

target:
